            check("small words stay down", "The Lord of the Rings", HeadlineCaser.toTitleCase("the lord of the rings"));
            check("mixed input case", "A Tale of Two Cities", HeadlineCaser.toTitleCase("a tale OF two cities"));
            check("first and last always up", "To Be or Not to Be", HeadlineCaser.toTitleCase("to be or not to be"));
