import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;

public class HeadlineCaser {

    static final Set<String> SMALL_WORDS = new HashSet<>(Arrays.asList(
            "a", "an", "and", "as", "at", "but", "by", "for", "in",
            "nor", "of", "on", "or", "the", "to", "up"));

    public static String toTitleCase(String text) {
        String trimmed = text.trim();
        if (trimmed.isEmpty()) {
            return "";
        }
        String[] words = trimmed.split("\\s+");
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < words.length; i++) {
            String lower = words[i].toLowerCase();
            boolean inTheMiddle = i > 0 && i < words.length - 1;
            String piece;
            if (inTheMiddle && SMALL_WORDS.contains(lower)) {
                piece = lower;
            } else {
                piece = Character.toUpperCase(lower.charAt(0)) + lower.substring(1);
            }
            if (i > 0) {
                out.append(' ');
            }
            out.append(piece);
        }
        return out.toString();
    }
}
